import katex from "katex";
import "katex/dist/katex.min.css";
import { useMemo } from "react";

/**
 * LaTeX rendered with KaTeX and inserted as HTML. The LaTeX is generated by the app; the only text a
 * user typed in it is a saved gate's label, inside \text{} with TeX's special characters removed
 * (format/bench.ts). KaTeX escapes text, and with `trust` off it renders no links, HTML or classes.
 */
export function Tex({ tex, display = false, className }: { tex: string; display?: boolean; className?: string }) {
  const html = useMemo(() => katex.renderToString(tex, { displayMode: display, throwOnError: false, trust: false }), [tex, display]);
  return <span className={className} dangerouslySetInnerHTML={{ __html: html }} />;
}
